class Solution { private data class Transaction(val raw:String,val name:String,val time:Int,val amount:Int,val city:String);fun invalidTransactions(input:Array<String>):List<String>{val transactions=input.map{raw->val parts=raw.split(',');Transaction(raw,parts[0],parts[1].toInt(),parts[2].toInt(),parts[3])};val invalid=BooleanArray(input.size){transactions[it].amount>1000};for(i in transactions.indices)for(j in i+1 until transactions.size){val a=transactions[i];val b=transactions[j];if(a.name==b.name&&a.city!=b.city&&kotlin.math.abs(a.time-b.time)<=60){invalid[i]=true;invalid[j]=true}};return input.indices.filter{invalid[it]}.map{input[it]}} }
